const SOURCES = INVENTORY_SOURCES.filter((s) => ["blavatsky-isis", "blavatsky-sd", "coleman-1895"].includes(s.key));

const METHOD =
  "Taken from the Theosophical University Press online edition (theosociety.org/pasadena), which reproduces the first editions page for page, compared word by word with the archive.org OCRs of separate printed copies (The Secret Doctrine vol. I: secretdoctrinesy0001hpbl_w8r1, the 1977 TUP facsimile bwb_C0-ADX-874 and the 1925 Theosophy Company facsimile in.ernet.dli.2015.62045; vol. II: the Wellcome Library's 1888 copy b24886142, secretdoctrinesy0002hpbl_o5q6, bwb_Y0-BMG-596 and in.ernet.dli.2015.62045; Isis Unveiled: Cornell's 1877 copies cu31924092304579 and -587, the Wellcome Library's 1878 printing b24886154, and india.history.resource.85989–90). Where two or more OCRs agreed on a word against the base and outnumbered it, their reading was taken; the readings the OCRs could not settle were checked on the page images, and every correction by hand, and every place where agreeing OCRs were overruled, is listed in scripts/texts/blavatsky-dzyan.py. The first editions' misprints are kept. Footnotes are left out unless printed as '[Footnote]'; the print's circumflexes and other accents are not reproduced, and words set in small capitals are given in ordinary capitals and lower case.";

const BOOKS = {
  isis: { sourceKey: "blavatsky-isis", title: "Isis Unveiled", year: 1877 },
  sd: { sourceKey: "blavatsky-sd", title: "The Secret Doctrine", year: 1888 },
} as const;

function hpbLayer(text: string, work: keyof typeof BOOKS, where: string): CorpusLayer {
  const book = BOOKS[work];
  return {
    key: "eng-blavatsky",
    layer: "primary_text",
    sourceKey: book.sourceKey,
    content: text,
    language: "English",
    licence: "public_domain",
    evidence: `H. P. Blavatsky, ${book.title} (first edition, ${book.year}), ${where}. Public domain. ${METHOD}`,
  };
}

const volumeLabel = (v: 1 | 2) => (v === 1 ? "I" : "II");

