// ---------------------------------------------------------------------------
// BUILDING THE PASSAGES
// ---------------------------------------------------------------------------

function stanzaKey(s: HpbStanza) {
  return `${PREFIX}.${s.book}.${s.stanza}`;
}

function selectionKey(s: HpbSelection) {
  return `${PREFIX}.${s.work === "isis" ? "isis" : "sd"}.${s.id.split(".").slice(1).join(".")}`;
}

function themesOf(meta: { themes?: [string, string][] }) {
  return meta.themes?.map(([themeKey, note]) => ({ themeKey, note }));
}

function partPassage(id: keyof typeof PARTS, dates?: CorpusPassageDate[]): CorpusPassage {
  const meta = PARTS[id];
  const key = `${PREFIX}.${id}`;
  return {
    key,
    divisionKind: "part",
    label: meta.label,
    reference: meta.reference,
    sourceKey: meta.sourceKey,
    summary: meta.summary,
    notes: meta.notes,
    verificationStatus: "unverified",
    layers: [],
    dates,
    themes: themesOf(meta),
    images: imagesFor(BLAVATSKY_IMAGES, key),
  };
}

function stanzaPassages(book: "cosmo" | "anthro"): CorpusPassage[] {
  return HPB_STANZAS.filter((s) => s.book === book).map((s) => {
    const key = stanzaKey(s);
    const meta = STANZA_META[`${s.book}.${s.stanza}`];
    const where = `vol. ${volumeLabel(s.volume)}, ${s.pages}`;
    return {
      key,
      parentKey: `${PREFIX}.${book}`,
      divisionKind: "section",
      label: `Stanza ${NUMERALS[s.stanza]}: ${meta.title}`,
      reference: `The Secret Doctrine (1888), ${where}`,
      sourceKey: "blavatsky-sd",
      summary: meta.summary,
      notes: [`The stanza as first printed, before the commentary; the commentary on it, headed '${meta.title}' in the book's table of contents, begins on vol. ${volumeLabel(s.volume)}, p. ${meta.commentaryPage}, and is not imported.`, meta.notes].filter(Boolean).join(" "),
      verificationStatus: "unverified",
      layers: [hpbLayer(s.text, "sd", `${where}, Stanza ${NUMERALS[s.stanza]}`)],
      themes: themesOf(meta),
      images: imagesFor(BLAVATSKY_IMAGES, key),
    };
  });
}

function selectionPassages(group: "isis" | "sd.1" | "sd.2"): CorpusPassage[] {
  return HPB_SELECTIONS.filter((s) => SELECTION_META[s.id].group === group).map((s) => {
    const key = selectionKey(s);
    const meta = SELECTION_META[s.id];
    const book = BOOKS[s.work];
    const where = `vol. ${volumeLabel(s.volume)}, ${s.pages}`;
    return {
      key,
      parentKey: `${PREFIX}.${group}`,
      divisionKind: "section",
      label: meta.label,
      reference: `${book.title} (${book.year}), ${where}`,
      sourceKey: book.sourceKey,
      summary: meta.summary,
      notes: meta.notes,
      verificationStatus: "unverified",
      layers: [hpbLayer(s.text, s.work, where)],
      themes: themesOf(meta),
      images: imagesFor(BLAVATSKY_IMAGES, key),
    };
  });
}

function buildPassages(): CorpusPassage[] {
  return [
    partPassage("isis", ISIS_DATES),
    ...selectionPassages("isis"),
    partPassage("sd.1", SD_DATES),
    ...selectionPassages("sd.1"),
    partPassage("cosmo", DZYAN_DATES),
    ...stanzaPassages("cosmo"),
    partPassage("anthro"),
    ...stanzaPassages("anthro"),
    partPassage("sd.2"),
    ...selectionPassages("sd.2"),
  ];
}

